_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
_VENUES = {'NYSE', 'NASDAQ', 'IEX'}

def generate_route_id(venue: str) -> str:
    if venue not in _VENUES:
        raise ValueError('unsupported venue')
    suffix = ''.join((secrets.choice(_ALPHABET) for _ in range(12)))
    return f'{venue}-{suffix}'

def route_order(symbol: str, quantity: int, limit_price: float, venue: str) -> dict[str, object]:
    if not symbol or quantity <= 0 or limit_price <= 0 or (venue not in _VENUES):
        raise ValueError('invalid order')
    return {'symbol': symbol, 'quantity': quantity, 'limit_price': limit_price, 'venue': venue, 'route_id': generate_route_id(venue)}

