def schedule_port(requester: dict, service: dict, port: int, reservations: list[dict]) -> list[dict]:
    if not isinstance(port, int) or isinstance(port, bool) or (not 1 <= port <= 65535):
        raise ValueError('invalid port')
    if requester.get('tenant_id') != service.get('tenant_id'):
        raise PermissionError('not permitted')
    if requester.get('id') != service.get('owner_id') and requester.get('role') != 'admin':
        raise PermissionError('not permitted')
    if any((r.get('service_id') == service.get('id') and r.get('port') == port for r in reservations)):
        raise ValueError('port already reserved')
    result = list(reservations)
    result.append({'service_id': service['id'], 'port': port, 'owner_id': requester['id']})
    result.sort(key=lambda r: (r['service_id'], r['port']))
    return result

