def read_forecast(base_dir: str, relative_name: str) -> list[tuple[str, float]]:
    base = Path(base_dir).resolve()
    candidate = (base / relative_name).resolve()
    try:
        candidate.relative_to(base)
    except ValueError:
        raise ValueError('forecast path outside base directory')
    with candidate.open(newline='', encoding='utf-8') as stream:
        rows = list(csv.reader(stream))
    if not rows:
        return []
    if rows[0] != ['timestamp', 'demand']:
        raise ValueError('invalid forecast header')
    result = []
    for row in rows[1:]:
        if len(row) != 2:
            raise ValueError('invalid forecast row')
        try:
            demand = float(row[1])
        except ValueError:
            raise ValueError('invalid demand value')
        result.append((row[0], demand))
    return sorted(result, key=lambda item: item[0])

