import os
import tempfile

def export_lunch_payments(records: list[dict[str, object]], destination: str) -> int:
    rows = []
    for record in records:
        amount = record['amount_cents']
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError('amount_cents must be a nonnegative integer')
        if record['paid']:
            rows.append((str(record['student_id']), amount))
    rows.sort(key=lambda row: row[0])
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['student_id', 'amount_cents'])
            writer.writerows(rows)
        os.replace(temporary, destination)
        temporary = ''
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
    return len(rows)

