import hmac

def verify_shelter_registration(record: str, key: bytes) -> dict:
    try:
        supplied, payload = record.split('.', 1)
        shelter, family_text, priority = payload.split('|')
    except ValueError as exc:
        raise ValueError('invalid record') from exc
    expected = hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        families = int(family_text)
    except ValueError as exc:
        raise ValueError('invalid family count') from exc
    if families < 0:
        raise ValueError('invalid family count')
    if not shelter.strip():
        raise ValueError('invalid shelter')
    if priority not in {'low', 'normal', 'high'}:
        raise ValueError('invalid priority')
    return {'shelter': shelter, 'families': families, 'priority': priority}

