import xml.etree.ElementTree as ET

def route_kitchen_orders(xml_text: str) -> dict[str, list[str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'kitchen_orders':
        raise ValueError('invalid root element')
    grouped: dict[str, list[str]] = {}
    for order in root:
        if order.tag != 'order':
            continue
        order_id = order.get('id')
        station = order.get('station')
        if order_id is None or station is None:
            raise ValueError('order attributes are required')
        grouped.setdefault(station, []).append(order_id)
    return {station: grouped[station] for station in sorted(grouped)}

