    selected = [visit for visit in visits if visit['verified'] is True]
    selected.sort(key=lambda visit: (str(visit['visit_date']), str(visit['caregiver'])))
    directory = os.path.dirname(os.path.abspath(destination))
    temporary_path = tempfile.mktemp(dir=directory, prefix='visits-', suffix='.csv')
    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['visit_date', 'patient', 'caregiver', 'status'])
            for visit in selected:
                writer.writerow([visit['visit_date'], visit['patient'], visit['caregiver'], 'VERIFIED'])
        os.replace(temporary_path, destination)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    return len(selected)

