import ast
import operator

def _evaluate(rule, values):
    try:
        tree = ast.parse(rule, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in values:
                    raise ValueError()
                return values[node.id]
            if isinstance(node, ast.BinOp):
                ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
                if type(node.op) not in ops:
                    raise ValueError()
                return ops[type(node.op)](visit(node.left), visit(node.right))
            if isinstance(node, ast.UnaryOp):
                if isinstance(node.op, ast.UAdd):
                    return +visit(node.operand)
                if isinstance(node.op, ast.USub):
                    return -visit(node.operand)
                if isinstance(node.op, ast.Not):
                    return not visit(node.operand)
                raise ValueError()
            if isinstance(node, ast.BoolOp):
                result = visit(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And):
                        if not result:
                            return result
                    elif isinstance(node.op, ast.Or):
                        if result:
                            return result
                    else:
                        raise ValueError()
                    result = visit(item)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                funcs = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
                for op, item in zip(node.ops, node.comparators):
                    if type(op) not in funcs:
                        raise ValueError()
                    right = visit(item)
                    if not funcs[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
            raise ValueError()
        return visit(tree)
    except (SyntaxError, NameError, TypeError, ZeroDivisionError, ValueError, OverflowError):
        raise ValueError()

def select_catering_quotes(events: list[dict[str, float]], rule: str) -> list[dict[str, float]]:
    selected = []
    for event in events:
        values = {key: event[key] for key in ('guests', 'menu_price', 'service_fee', 'travel_miles')}
        if _evaluate(rule, values):
            quote = round(event['guests'] * event['menu_price'] + event['service_fee'] + event['travel_miles'] * 2, 2)
            selected.append({'name': event['name'], 'quote': quote})
    return sorted(selected, key=lambda item: (-item['quote'], item['name']))

