            writer = csv.writer(handle)
            writer.writerow(['player_id', 'server', 'started_at'])
            writer.writerows(rows)
        os.replace(temporary, destination)
        temporary = ''
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
    return len(rows)

