import xml.sax
import xml.sax.handler

class _PickupHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.depth = 0
        self.pickups = []

    def startElement(self, name, attrs):
        if self.depth == 0:
            self.root = name
        elif self.depth == 1 and name == 'pickup':
            required = ('date', 'material', 'address')
            if any((attrs.get(key) is None for key in required)):
                raise ValueError('pickup is missing an attribute')
            self.pickups.append({key: attrs.get(key) for key in required})
        self.depth += 1

    def endElement(self, name):
        self.depth -= 1

def parse_pickup_schedule(xml_text: str) -> list[dict[str, str]]:
    handler = _PickupHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'schedules':
        raise ValueError('invalid root element')
    return sorted(handler.pickups, key=lambda item: (item['date'], item['address'], item['material']))

