def calculate_rewards(path: str, category: str) -> int:
    if not category:
        raise ValueError('category must not be empty')
    result = subprocess.run(['sort', path], check=True, capture_output=True, text=True)
    total = 0
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split(',')
        if len(fields) != 2:
            raise ValueError('invalid transaction')
        name, amount_text = fields
        try:
            amount = int(amount_text)
        except ValueError as exc:
            raise ValueError('invalid transaction') from exc
        if amount < 0:
            raise ValueError('invalid transaction')
        if name == category:
            total += amount // 1000
    return total

