import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, values)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id in values:
            return values[node.id]
        raise NameError(node.id)
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in operations:
            raise ValueError('unsupported operator')
        return operations[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        operations = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}
        if type(node.op) not in operations:
            raise ValueError('unsupported operator')
        return operations[type(node.op)](value)
    if isinstance(node, ast.BoolOp):
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif isinstance(node.op, ast.Or):
                if result:
                    return result
            else:
                raise ValueError('unsupported operator')
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for operation, child in zip(node.ops, node.comparators):
            right = _evaluate(child, values)
            functions = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            if type(operation) not in functions:
                raise ValueError('unsupported comparison')
            if not functions[type(operation)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
        return getattr(__builtins__ if isinstance(__builtins__, dict) else __builtins__, node.func.id)(*[_evaluate(arg, values) for arg in node.args])
    raise ValueError('unsupported expression')

def select_tickets(tickets: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval')
    selected = []
    for ticket in tickets:
        values = {name: ticket[name] for name in ('price', 'days', 'age')}
        if _evaluate(tree, values):
            selected.append(ticket)
    return sorted(selected, key=lambda ticket: ticket['price'])

