import os
_ITERATIONS = 100000

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and 4 <= len(pin) <= 8 and pin.isdecimal() and pin.isascii()

def encode_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('PIN must contain 4 to 8 decimal digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('ascii'), salt, _ITERATIONS)
    return base64.b64encode(salt).decode('ascii') + ':' + digest.hex()

def verify_pin(stored: str, pin: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = base64.b64decode(salt_text.encode('ascii'), validate=True)
        expected = bytes.fromhex(digest_text)
    except (ValueError, UnicodeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode('ascii'), salt, _ITERATIONS)
    return hmac.compare_digest(actual, expected)

