import ast
import operator

def filter_concerts(concerts: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval').body
    allowed = {'price', 'available', 'rating', 'capacity'}
    functions = {'min': min, 'max': max, 'round': round}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in functions:
                return functions[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp):
            ops = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](evaluate(node.operand, values))
        if isinstance(node, ast.BoolOp):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            for op, right_node in zip(node.ops, node.comparators):
                if type(op) not in ops:
                    raise ValueError('unsupported expression')
                right = evaluate(right_node, values)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in functions):
            return functions[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('unsupported expression')
    return [concert for concert in concerts if evaluate(tree, {name: concert[name] for name in allowed})]

