import xml.etree.ElementTree as ET

def parse_planning_feed(xml_text: str) -> list[dict[str, str | float]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'plans':
        raise ValueError('invalid root')
    projects = []
    for element in root.findall('project'):
        project_id = element.get('id')
        region = element.get('region')
        name_element = element.find('name')
        area_element = element.find('area')
        if project_id is None or region is None or name_element is None or (area_element is None):
            raise ValueError('incomplete project')
        if name_element.text is None or area_element.text is None:
            raise ValueError('incomplete project')
        try:
            area = float(area_element.text.strip())
        except ValueError as exc:
            raise ValueError('invalid area') from exc
        projects.append({'id': project_id.strip(), 'region': region.strip(), 'name': name_element.text.strip(), 'area': area})
    return sorted(projects, key=lambda project: project['id'])

