import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.Not):
            return not value
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        for kind, function in operations.items():
            if isinstance(node.op, kind):
                return function(left, right)
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = _evaluate(node.values[0], values)
            for child in node.values[1:]:
                if not result:
                    return result
                result = _evaluate(child, values)
            return result
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if result:
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, values)
            functions = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            function = next((f for kind, f in functions.items() if isinstance(op, kind)), None)
            if function is None or not function(left, right):
                return False
            left = right
        return True
    raise ValueError('unsupported expression')

def select_beneficiaries(beneficiaries: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval').body
    selected = [item for item in beneficiaries if _evaluate(tree, item)]
    return sorted(selected, key=lambda item: (-item['benefit_percentage'], item['name']))

