import os

def _hash_password(password: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return base64.b64encode(salt).decode('ascii') + ':' + base64.b64encode(digest).decode('ascii')

def create_operator_credential(operator_id: str, password: str) -> dict:
    if not operator_id or not password:
        raise ValueError('operator_id and password must not be empty')
    return {'operator_id': operator_id, 'password_hash': _hash_password(password)}

def verify_operator_credential(credential: dict, operator_id: str, password: str) -> bool:
    if credential.get('operator_id') != operator_id:
        return False
    try:
        salt_text, digest_text = credential['password_hash'].split(':')
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
    except (KeyError, ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

