import hashlib
import hmac
import json

def load_catalog_update(payload: str, signature: str, key: str) -> list[dict[str, object]]:
    expected = hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        products = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(products, list):
        raise ValueError('invalid payload')
    for product in products:
        if not isinstance(product, dict):
            raise ValueError('invalid product')
        if not isinstance(product.get('id'), int) or isinstance(product.get('id'), bool):
            raise ValueError('invalid product')
        if not isinstance(product.get('name'), str):
            raise ValueError('invalid product')
        price = product.get('price')
        if not isinstance(price, (int, float)) or isinstance(price, bool):
            raise ValueError('invalid product')
        if not isinstance(product.get('category'), str):
            raise ValueError('invalid product')
    return sorted(products, key=lambda product: (product['price'], product['name']))

