import os
from pathlib import Path

def save_backup(base_dir: str, relative_name: str, configuration: str) -> str:
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if target != base and base not in target.parents:
        raise ValueError('backup path is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(configuration, encoding='utf-8')
    return str(target)

