        if not isinstance(employee, str) or not employee or (not isinstance(asset, str)) or (not asset):
            raise ValueError('employee and asset must be non-empty strings')
        rows.append((employee, asset))
    rows.sort()
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='asset-report-', suffix='.csv', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('employee', 'asset'))
            writer.writerows(rows)
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

