import zipfile
from pathlib import Path

def extract_fasta_archive(archive_path: str, output_dir: str) -> dict[str, int]:
    base = Path(output_dir).resolve()
    result = {}
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            target = (base / info.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive member is outside output directory')
            if not info.filename.endswith('.fa'):
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            data = archive.read(info)
            target.write_bytes(data)
            text = data.decode('utf-8')
            length = sum((len(''.join(line.split())) for line in text.splitlines() if line.strip() and (not line.startswith('>'))))
            result[info.filename] = length
    return result

