import hashlib
import hmac
import json
import os

def sign_vineyard_record(record: dict[str, object]) -> str:
    required = ('vineyard', 'vintage', 'varietal', 'tons')
    if any((field not in record for field in required)):
        raise ValueError('record is missing a required field')
    vintage = record['vintage']
    tons = record['tons']
    if not isinstance(vintage, int) or isinstance(vintage, bool) or (not 1900 <= vintage <= 2100):
        raise ValueError('vintage must be between 1900 and 2100')
    if not isinstance(tons, (int, float)) or isinstance(tons, bool) or tons < 0:
        raise ValueError('tons must be non-negative')
    key = os.environ.get('VINEYARD_SIGNING_KEY')
    if key is None:
        raise RuntimeError('VINEYARD_SIGNING_KEY is not set')
    payload = json.dumps(record, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    return hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()

