import xml.sax.handler

class _ConsentHandler(xml.sax.handler.ContentHandler):

    def __init__(self) -> None:
        super().__init__()
        self.result = []

    def startElement(self, name, attrs):
        if name != 'consent':
            return
        status = attrs.get('status')
        if status not in {'granted', 'denied'}:
            raise ValueError('invalid status')
        if status == 'granted':
            self.result.append((attrs['user'], attrs['purpose']))

def parse_consents(xml_text: str) -> list[tuple[str, str]]:
    handler = _ConsentHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except ValueError:
        raise
    except xml.sax.SAXException as exc:
        raise ValueError('malformed XML') from exc
    return sorted(handler.result)

