        raise PermissionError('requester is not permitted')
    if not isinstance(start_minute, int) or isinstance(start_minute, bool) or (not 0 <= start_minute <= 1439):
        raise ValueError('invalid start minute')
    if not any((track.get('id') == track_id for track in playlist.get('tracks', []))):
        raise ValueError('unknown track')
    entry = {'track_id': track_id, 'start_minute': start_minute}
    playlist['schedule'].append(entry)
