import hashlib
import hmac
import os

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and len(pin) == 4 and pin.isdecimal()

def hash_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('PIN must contain exactly four digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def record_catch(pin: str, stored: str, species: str, kilograms: float) -> dict:
    if not verify_pin(pin, stored):
        raise PermissionError('invalid PIN')
    name = species.strip().lower()
    if not name or kilograms <= 0:
        raise ValueError('invalid catch data')
    return {'species': name, 'kilograms': round(kilograms, 2)}

