import hmac
import os
_ITERATIONS = 100000

def hash_api_secret(secret: str) -> str:
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, _ITERATIONS)
    return salt.hex() + '$' + digest.hex()

def verify_api_secret(secret: str, stored: str) -> bool:
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, _ITERATIONS)
    return hmac.compare_digest(actual, expected)

