import tempfile

def calculate_rewards(transactions: list[tuple[str, float]], rates: dict[str, float]) -> dict[str, float]:
    totals = {}
    for category, amount in transactions:
        if amount < 0 or category not in rates:
            raise ValueError('invalid transaction')
        totals[category] = totals.get(category, 0.0) + amount * rates[category]
    return {category: round(totals[category], 2) for category in sorted(totals)}

def export_rewards(transactions: list[tuple[str, float]], rates: dict[str, float], destination: str) -> dict[str, float]:
    rewards = calculate_rewards(transactions, rates)
    directory = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=directory, prefix='rewards-', suffix='.csv')
    try:
        with os.fdopen(descriptor, 'w', newline='') as stream:
            stream.write('category,rewards\n')
            for category, amount in rewards.items():
                stream.write(f'{category},{amount:.2f}\n')
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return rewards

