import os

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and 4 <= len(pin) <= 12 and pin.isdigit()

def hash_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_pin(pin: str, stored_hash: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored_hash, str):
        return False
    try:
        salt_text, digest_text = stored_hash.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return actual == expected

def issue_pass(pin: str, zones: list[str]) -> dict[str, object]:
    if not _valid_pin(pin):
        raise ValueError('invalid PIN')
    if not zones:
        raise ValueError('at least one zone is required')
    return {'zones': sorted(set(zones)), 'pin_hash': hash_pin(pin)}

