def ingest_meter_reading(xml_text: str) -> dict:

    class ReadingHandler(xml.sax.handler.ContentHandler):

        def __init__(self):
            self.values = {}
            self.current = None
            self.parts = []
            self.root = None

        def startElement(self, name, attrs):
            if self.root is None:
                self.root = name
            self.current = name
            self.parts = []

