import xml.sax.handler

class _VisitHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.values = {}
        self.current = None
        self.parts = []
        self.root = None

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name in ('visit_id', 'patient', 'date', 'verified'):
            self.current = name
            self.parts = []

    def characters(self, content):
        if self.current is not None:
            self.parts.append(content)

    def endElement(self, name):
        if name == self.current:
            self.values[name] = ''.join(self.parts).strip()
            self.current = None
            self.parts = []

def parse_visit(xml_text: str) -> dict[str, object]:
    handler = _VisitHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except xml.sax.SAXException as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'visit':
        raise ValueError('invalid root')
    values = {}
