import hashlib
import hmac
import json

def verify_telemetry(payload: bytes, signature: str, secret: bytes) -> dict:
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict):
        raise ValueError('invalid payload')
    device_id = data.get('device_id')
    timestamp = data.get('timestamp')
    readings = data.get('readings')
    if not isinstance(device_id, str) or not device_id:
        raise ValueError('invalid payload')
    if not isinstance(timestamp, int) or isinstance(timestamp, bool):
        raise ValueError('invalid payload')
    if not isinstance(readings, dict):
        raise ValueError('invalid payload')
    for key, value in readings.items():
        if not isinstance(key, str) or not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError('invalid payload')
    return {'device_id': device_id, 'timestamp': timestamp, 'readings': {key: readings[key] for key in sorted(readings)}}

