import os
import tempfile

def export_tax_report(transactions: list[dict[str, object]], destination: str) -> int:
    fields = ('date', 'asset', 'proceeds', 'cost_basis')
    for transaction in transactions:
        if any((field not in transaction for field in fields)):
            raise ValueError('missing transaction field')
    ordered = sorted(transactions, key=lambda item: str(item['date']))
    temporary = tempfile.mktemp(suffix='.csv')
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(('date', 'asset', 'proceeds', 'cost_basis', 'gain'))
            for transaction in ordered:
                proceeds = float(transaction['proceeds'])
                cost_basis = float(transaction['cost_basis'])
                writer.writerow((transaction['date'], transaction['asset'], f'{proceeds:.2f}', f'{cost_basis:.2f}', f'{proceeds - cost_basis:.2f}'))
        os.replace(temporary, destination)
        return len(ordered)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)

