def parse_artifact(manifest: str, key: bytes) -> dict[str, object]:
    fields = manifest.split('|')
    if len(fields) != 4:
        raise ValueError('invalid manifest')
    name, size_text, checksum, signature = fields
    if not name or not size_text.isdecimal():
        raise ValueError('invalid manifest')
    size = int(size_text)
    if len(checksum) != 64 or any((c not in '0123456789abcdef' for c in checksum)):
