import ast
import operator

def _evaluate(rule, values):
    try:
        tree = ast.parse(rule, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
                return node.value
            if isinstance(node, ast.Name):
                return values[node.id]
            if isinstance(node, ast.BinOp):
                ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
                return ops[type(node.op)](visit(node.left), visit(node.right))
            if isinstance(node, ast.UnaryOp):
                ops = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}
                return ops[type(node.op)](visit(node.operand))
            if isinstance(node, ast.BoolOp):
                result = visit(node.values[0])
                for part in node.values[1:]:
                    if isinstance(node.op, ast.And):
                        if not result:
                            return result
                    elif result:
                        return result
                    result = visit(part)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                checks = []
                ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    checks.append(ops[type(op)](left, right))
                    left = right
                return all(checks)
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
            raise ValueError('invalid expression')
        return visit(tree)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid expression') from exc

def rank_notifications(notifications: list[dict[str, object]], rule: str, limit: int) -> list[dict[str, object]]:
    if limit < 0:
        raise ValueError('limit must not be negative')
    selected = [item for item in notifications if _evaluate(rule, item)]
    selected.sort(key=lambda item: item['score'], reverse=True)
    return selected[:limit]

