from pathlib import Path
import zipfile

def extract_telemetry_archive(archive_path: str, destination_dir: str) -> list[str]:
    base = Path(destination_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    extracted = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir() or not info.filename.endswith('.csv'):
                continue
            target = (base / info.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('member path is not beneath destination')
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(info))
            extracted.append(info.filename)
    return sorted(extracted)

import hashlib
import hmac
import os

def _hash_pin(pin: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def create_notification(recipient: str, service_date: str, pin: str) -> dict[str, str]:
    if len(pin) != 4 or not pin.isdecimal():
        raise ValueError('pin must contain exactly four digits')
    return {'recipient': recipient, 'service_date': service_date, 'message': f'Jury duty for {service_date}: please review your notification.', 'pin_hash': _hash_pin(pin)}

def verify_pin(pin: str, stored_pin: str) -> bool:
    try:
        salt_text, digest_text = stored_pin.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

