def build_weather_briefing(requester: dict, flight: dict, reports: list[dict]) -> str:
    same_tenant = requester.get('tenant_id') == flight.get('tenant_id')
    is_owner = requester.get('id') == flight.get('owner_id')
    is_dispatcher = 'dispatcher' in requester.get('roles', [])
    if not same_tenant or not (is_owner or is_dispatcher):
        raise PermissionError('not permitted')
    airports = [flight['origin'], flight['destination']]
    newest = {}
    for report in reports:
        if report.get('airport') not in airports:
            continue
        if not isinstance(report.get('issued_at'), int):
            raise ValueError('issued_at must be an integer')
        airport = report['airport']
        if airport not in newest or report['issued_at'] > newest[airport]['issued_at']:
            newest[airport] = report
    lines = [f"Flight {flight['id']} weather briefing"]
    for airport in airports:
        if airport in newest:
            lines.append(f"{airport}: {newest[airport]['summary']}")
    return '\n'.join(lines)

