import hashlib
import hmac
import os

def hash_access_code(code: str) -> str:
    if not code:
        raise ValueError('code must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_access_code(code: str, stored: str) -> bool:
    if not code:
        raise ValueError('code must not be empty')
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def rank_events(events: list[dict], minimum_energy: float, code: str, stored_code: str) -> list[str]:
    if not verify_access_code(code, stored_code):
        return []
    selected = [event for event in events if event['energy'] >= minimum_energy]
    selected.sort(key=lambda event: (-event['energy'], event['id']))
    return [event['id'] for event in selected]

