import xml.sax.handler

class _RegistrationHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.records = []
        self.current = None
        self.field = None
        self.value = []

    def startElement(self, name, attrs):
        if name == 'registration':
            self.current = {}
        elif name in ('domain', 'registrant') and self.current is not None:
            self.field = name
            self.value = []

    def characters(self, content):
        if self.field is not None:
            self.value.append(content)

    def endElement(self, name):
        if name in ('domain', 'registrant') and self.current is not None:
            self.current[name] = ''.join(self.value).strip()
            self.field = None
            self.value = []
        elif name == 'registration':
            if 'domain' not in self.current or 'registrant' not in self.current:
                raise ValueError('registration is incomplete')
            if not self.current['domain'] or not self.current['registrant']:
                raise ValueError('registration contains an empty value')
            self.records.append((self.current['domain'], self.current['registrant']))
            self.current = None

def parse_registrations(xml_text: str) -> list[tuple[str, str]]:
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    handler = _RegistrationHandler()
    parser.setContentHandler(handler)
    parser.parse(io.StringIO(xml_text))
    return sorted(handler.records, key=lambda item: item[0])

import csv
import os
import tempfile
from decimal import Decimal

def export_cart(items: list[tuple[str, float, int]], destination: str) -> float:
    total = Decimal('0')
    prepared = []
    for name, price, quantity in items:
        if price < 0 or quantity < 1:
            raise ValueError('invalid cart item')
        unit_price = Decimal(str(price))
        line_total = unit_price * quantity
        prepared.append((name, unit_price, quantity, line_total))
        total += line_total
    temporary = tempfile.mktemp()
    try:
        with open(temporary, 'w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(['name', 'unit_price', 'quantity', 'line_total'])
            for name, price, quantity, line_total in prepared:
                writer.writerow([name, f'{price:.2f}', quantity, f'{line_total:.2f}'])
            writer.writerow(['TOTAL', '', '', f'{total:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return float(total)

