import hashlib
import os

def recommend_size(chest_cm: float) -> str:
    if chest_cm <= 0:
        raise ValueError('chest measurement must be positive')
    if chest_cm < 90:
        return 'S'
    if chest_cm < 100:
        return 'M'
    if chest_cm < 110:
        return 'L'
    return 'XL'

def create_size_record(password: str, chest_cm: float) -> str:
    size = recommend_size(chest_cm)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return f'{size}:{salt.hex()}:{digest.hex()}'

def verify_size_record(record: str, password: str) -> bool:
    try:
        size, salt_text, digest_text = record.split(':')
        if size not in {'S', 'M', 'L', 'XL'}:
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return len(salt) == 16 and len(expected) == 32 and (actual == expected)
    except (ValueError, TypeError):
        return False

