import hmac
import json

def verify_inheritance_notice(payload: str, signature: str, secret: str) -> bool:
    try:
        data = json.loads(payload)
        if len(signature) != 64:
            return False
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError, json.JSONDecodeError):
        return False
    if not isinstance(data, dict):
        return False
    if not isinstance(data.get('beneficiary'), str) or not data['beneficiary']:
        return False
    amount = data.get('amount')
    if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
        return False
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).digest()
    return hmac.compare_digest(expected, supplied)

