import xml.etree.ElementTree as ET

def parse_campaign(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
        if root.tag != 'campaign' or 'name' not in root.attrib:
            raise ValueError
        goal_node = root.find('goal')
        if goal_node is None or goal_node.text is None:
            raise ValueError
        donations = []
        for node in root.findall('donation'):
            donations.append({'donor': node.attrib['donor'], 'amount': float(node.attrib['amount'])})
        donations.sort(key=lambda item: item['amount'], reverse=True)
        return {'name': root.attrib['name'], 'goal': float(goal_node.text), 'donations': donations}
    except (ET.ParseError, KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid campaign XML') from exc

