import os

def issue_moderator_credential(passphrase: str) -> str:
    if not passphrase:
        raise ValueError('passphrase must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', passphrase.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_moderator_credential(record: str, passphrase: str) -> bool:
    if not passphrase or not isinstance(record, str):
        return False
    parts = record.split('$')
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', passphrase.encode(), salt, 100000)
    return actual == expected

