import ast
import operator

def _evaluate(expression, values):
    try:
        tree = ast.parse(expression, mode='eval').body
    except (SyntaxError, ValueError, TypeError) as exc:
        raise ValueError('invalid expression') from exc
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compare = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise ValueError('unknown name')
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp):
            result = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = visit(child)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if type(op) not in compare or not compare[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('invalid expression')
    return visit(tree)

def rank_reservations(reservations: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    selected = []
    for reservation in reservations:
        nights = reservation['nights']
        rate = reservation['rate']
        total = nights * rate
        if _evaluate(rule, {'nights': nights, 'rate': rate, 'total': total}):
            selected.append((total, reservation))
    return [reservation for _, reservation in sorted(selected, key=lambda item: -item[0])]

