import ast
import operator

def _value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in env:
            raise ValueError('unknown variable')
        return env[node.id]
    if isinstance(node, ast.BinOp):
        left = _value(node.left, env)
        right = _value(node.right, env)
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        for kind, fn in ops.items():
            if isinstance(node.op, kind):
                return fn(left, right)
    if isinstance(node, ast.UnaryOp):
        value = _value(node.operand, env)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
        if isinstance(node.op, ast.Not):
            return not value
    if isinstance(node, ast.BoolOp):
        values = [_value(item, env) for item in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.Compare):
        left = _value(node.left, env)
        checks = []
        for op, part in zip(node.ops, node.comparators):
            right = _value(part, env)
            fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
            if fn is None:
                raise ValueError('invalid rule')
            checks.append(fn(left, right))
            left = right
        return all(checks)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
        args = [_value(arg, env) for arg in node.args]
        if len(args) < 2:
            raise ValueError('invalid rule')
        return min(args) if node.func.id == 'min' else max(args)
    raise ValueError('invalid rule')

def select_deployments(deployments: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError('invalid rule')
    selected = []
    for deployment in deployments:
        env = {key: deployment[key] for key in ('replicas', 'available', 'ready')}
        if _value(tree, env):
            selected.append(deployment)
    selected.sort(key=lambda item: item['ready'], reverse=True)
    return [item['name'] for item in selected]

