    required = {'address', 'download_mbps', 'available'}
    for record in addresses:
        if not required.issubset(record):
            raise ValueError('missing required key')
    qualified = [record for record in addresses if record['available'] and record['download_mbps'] >= 100]
    qualified.sort(key=lambda record: record['address'])
    directory = os.path.dirname(os.path.abspath(output_path))
    temporary_path = tempfile.mktemp(dir=directory)
    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as file:
            writer = csv.writer(file)
            writer.writerow(['address', 'download_mbps'])
            for record in qualified:
                writer.writerow([record['address'], record['download_mbps']])
        os.replace(temporary_path, output_path)
    except BaseException:
        try:
            os.unlink(temporary_path)
        except OSError:
            pass
        raise
    return len(qualified)

