import ast
import operator

def _evaluate(rule, values):
    tree = ast.parse(rule, mode='eval').body
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.BoolOp):
            result = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = visit(item)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for operation, part in zip(node.ops, node.comparators):
                right = visit(part)
                if type(operation) not in comparisons or not comparisons[type(operation)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('invalid rule')
    return visit(tree)

def schedule_ports(containers: list[dict[str, object]], rule: str, start_port: int=8000, capacity: int=10) -> list[dict[str, object]]:
    selected = [c for c in containers if _evaluate(rule, {key: c[key] for key in ('cpu', 'memory', 'priority')})]
    if len(selected) > capacity:
        raise ValueError('capacity exceeded')
    selected = sorted(enumerate(selected), key=lambda item: (-item[1]['priority'], item[0]))
    return [{'name': c['name'], 'port': start_port + index, 'priority': c['priority']} for index, (_, c) in enumerate(selected)]

