def write_dispatch_report(base_dir: str, report_name: str, dispatch: dict[int, float]) -> str:
    if not report_name.endswith('.csv'):
        raise ValueError('report_name must identify a CSV file')
    for hour, power in dispatch.items():
        if not isinstance(hour, int) or not 0 <= hour <= 23:
            raise ValueError('hour must be between 0 and 23')
        if not isinstance(power, (int, float)):
            raise ValueError('power must be numeric')
    base = Path(base_dir).resolve()
    target = (base / report_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('report location is outside base directory')
    lines = ['hour,power_kw']
    lines.extend((f'{hour},{dispatch[hour]:.2f}' for hour in sorted(dispatch)))
    target.write_text('\n'.join(lines) + '\n')
    return str(target)

