def calculate_rewards(purchases: list[tuple[str, float]], points_per_dollar: int=1) -> dict[str, int]:
    if points_per_dollar <= 0:
        raise ValueError('points_per_dollar must be positive')
    totals: dict[str, int] = {}
    for category, amount in purchases:
        if amount < 0:
            raise ValueError('amount must not be negative')
        totals[category] = totals.get(category, 0) + int(amount * points_per_dollar)
    return totals

def save_rewards_report(base_dir: str, filename: str, purchases: list[tuple[str, float]], points_per_dollar: int=1) -> str:
    totals = calculate_rewards(purchases, points_per_dollar)
    base = Path(base_dir).resolve()
    target = (base / filename).resolve()
    if target != base and base not in target.parents:
        raise ValueError('filename is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    total = sum(totals.values())
    lines = [f'{category}: {totals[category]} points' for category in sorted(totals)]
    lines.append(f'total: {total} points')
    target.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    return str(target)

