import xml.sax.handler

class _NotificationHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.current = None
        self.text = []
        self.notices = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'notice':
            self.current = dict(attrs)
            self.text = []

    def characters(self, content):
        if self.current is not None:
            self.text.append(content)

    def endElement(self, name):
        if name == 'notice' and self.current is not None:
            required = ('id', 'date', 'recipient', 'court')
            if any((key not in self.current for key in required)):
                raise ValueError('missing notice attribute')
            self.current['message'] = ''.join(self.text).strip()
            self.notices.append(self.current)
            self.current = None

def parse_jury_notifications(xml_text: str) -> list[dict[str, str]]:
    handler = _NotificationHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    xml.sax.parseString(xml_text, handler)
    if handler.root != 'notifications':
        raise ValueError('invalid root')
    result = handler.notices
    result.sort(key=lambda item: (item['date'], item['id']))
