    if not name or not password:
        raise ValueError('name and password are required')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'name': name, 'password_hash': salt.hex() + '$' + digest.hex()}

