import pytest


def make_request(data, secret="box-key"):
    payload = json.dumps(data, separators=(",", ":")).encode()
    signature = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return payload, signature


def test_valid_webhook_returns_sorted_items():
    payload, signature = make_request({
        "type": "subscription_box",
        "box_id": "BX-17",
        "items": ["tea", "apples", "soap"]
    })
    assert verify_subscription_webhook(payload, signature, "box-key") == {
        "box_id": "BX-17",
        "items": ["apples", "soap", "tea"]
    }


def test_rejects_wrong_signature():
    payload, signature = make_request({
        "type": "subscription_box",
        "box_id": "BX-2",
        "items": ["coffee"]
    })
    altered = signature[:-1] + ("0" if signature[-1] != "0" else "1")
    with pytest.raises(ValueError):
        verify_subscription_webhook(payload, altered, "box-key")


def test_rejects_malformed_json_after_signature_check():
    payload = b"not json"
    signature = hmac.new(b"box-key", payload, hashlib.sha256).hexdigest()
    with pytest.raises(ValueError):
        verify_subscription_webhook(payload, signature, "box-key")


