import hashlib
import hmac
import json

def verify_subscription_webhook(payload: bytes, signature: str, secret: str) -> dict:
    try:
        supplied = bytes.fromhex(signature)
    except ValueError as exc:
        raise ValueError('invalid signature') from exc
    expected = hmac.new(secret.encode(), payload, hashlib.sha256).digest()
    if len(supplied) != len(expected) or not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or data.get('type') != 'subscription_box' or (not isinstance(data.get('box_id'), str)) or (not isinstance(data.get('items'), list)) or (not all((isinstance(item, str) for item in data['items']))):
        raise ValueError('invalid payload')
    return {'box_id': data['box_id'], 'items': sorted(data['items'])}

