import xml.etree.ElementTree as ET

def parse_visa_applications(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'applications':
        raise ValueError('unexpected root element')
    result = []
    for element in root.findall('application'):
        record = {'id': element.get('id', '')}
        for field in ('applicant', 'destination', 'status'):
            child = element.find(field)
            record[field] = '' if child is None or child.text is None else child.text.strip()
        if any((not record[field] for field in ('id', 'applicant', 'destination', 'status'))):
            raise ValueError('missing application value')
        result.append(record)
    return sorted(result, key=lambda item: item['id'])

