import xml.sax.handler

class _ApplicationHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.current = None
        self.field = None
        self.text = []
        self.records = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        elif name == 'application':
            self.current = {'id': attrs.get('id', '')}
        elif self.current is not None and name in ('applicant', 'destination', 'status'):
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.field == name:
            self.current[name] = ''.join(self.text).strip()
            self.field = None
            self.text = []
        elif name == 'application' and self.current is not None:
            self.records.append(self.current)
            self.current = None

def parse_visa_applications(xml_text: str) -> list[dict[str, str]]:
    handler = _ApplicationHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except xml.sax.SAXException as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'applications' or handler.current is not None:
        raise ValueError('unexpected XML structure')
    for record in handler.records:
        if any((not record.get(field, '') for field in ('id', 'applicant', 'destination', 'status'))):
            raise ValueError('missing application value')
    return sorted(handler.records, key=lambda item: item['id'])

