def save_access_report(base_dir: str, relative_name: str, events: list[tuple[str, str]]) -> str:
    root = Path(base_dir).resolve()
    target = (root / relative_name).resolve()
    if target == root or root not in target.parents:
        raise ValueError('target is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8') as handle:
        for badge_id, door_name in events:
            handle.write(f'{badge_id},{door_name}\n')
    return str(target)

