import hmac

def verify_flight_plan(message: str, access_code: str) -> dict:
    fields = [field.strip() for field in message.split('|')]
    if len(fields) != 5:
        raise ValueError('invalid flight plan')
    supplied_code, callsign, origin, destination, priority_text = fields
    if not hmac.compare_digest(supplied_code, access_code):
        raise ValueError('invalid access code')
    if not callsign or not origin or (not destination):
        raise ValueError('invalid flight plan')
    try:
        priority = int(priority_text)
    except ValueError:
        raise ValueError('invalid priority')
    if priority not in (1, 2, 3):
        raise ValueError('invalid priority')
    return {'callsign': callsign.upper(), 'origin': origin.upper(), 'destination': destination.upper(), 'priority': priority}

