def store_verification_document(base_dir: str, relative_name: str, content: bytes) -> str:
    if Path(relative_name).suffix.lower() not in {'.pdf', '.jpg', '.png'}:
        raise ValueError('unsupported document type')
    root = Path(base_dir).resolve()
    destination = (root / relative_name).resolve()
    try:
        destination.relative_to(root)
    except ValueError:
        raise ValueError('invalid document path')
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(content)
    return str(destination)

import hashlib
import hmac
import os

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and 4 <= len(pin) <= 12 and pin.isdecimal()

def hash_sampler_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_sampler_pin(pin: str, stored: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

