def collect_evidence(requester: dict, records: list[dict], case_id: str) -> list[dict]:
    matching = [record for record in records if record.get('case_id') == case_id]
    if not matching:
        return []
    for record in matching:
        for field in ('case_id', 'tenant_id', 'owner_id', 'captured_at', 'content'):
            if field not in record:
                raise ValueError(f'missing field: {field}')
        permitted = record['tenant_id'] == requester.get('tenant_id') and (record['owner_id'] == requester.get('id') or 'auditor' in requester.get('roles', []))
        if not permitted:
            raise PermissionError('not permitted')
    return [dict(record) for record in sorted(matching, key=lambda item: item['captured_at'])]

