import hmac
import json

def parse_consultation_callback(body: str, presented_token: str, configured_token: str) -> dict[str, object]:
    if not hmac.compare_digest(presented_token, configured_token):
        raise ValueError('token mismatch')
    try:
        data = json.loads(body)
    except (json.JSONDecodeError, TypeError):
        raise ValueError('invalid callback')
    if not isinstance(data, dict):
        raise ValueError('invalid callback')
    required = ('consultation_id', 'clinician', 'start', 'status')
    if any((field not in data for field in required)):
        raise ValueError('invalid callback')
    if not isinstance(data['consultation_id'], str) or not data['consultation_id']:
        raise ValueError('invalid callback')
    if not isinstance(data['clinician'], str) or not data['clinician']:
        raise ValueError('invalid callback')
    if not isinstance(data['start'], int) or isinstance(data['start'], bool):
        raise ValueError('invalid callback')
    if data['status'] not in ('scheduled', 'cancelled'):
        raise ValueError('invalid callback')
    return {field: data[field] for field in required}

