import xml.etree.ElementTree as ET

def parse_purchase_order(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'purchase_order':
        raise ValueError('wrong root element')
    order_id = root.get('id')
    vendor = root.get('vendor')
    if order_id is None or vendor is None:
        raise ValueError('missing order attribute')
    items = []
    total = 0
    for element in root:
        if element.tag != 'item':
            raise ValueError('unexpected element')
        sku = element.get('sku')
        quantity_text = element.get('quantity')
        price_text = element.get('unit_price_cents')
        if sku is None or quantity_text is None or price_text is None:
            raise ValueError('missing item attribute')
        try:
            quantity = int(quantity_text)
            price = int(price_text)
        except ValueError as exc:
            raise ValueError('invalid item value') from exc
        if quantity <= 0 or price < 0:
            raise ValueError('invalid item value')
        items.append({'sku': sku, 'quantity': quantity, 'unit_price_cents': price})
        total += quantity * price
    return {'order_id': order_id, 'vendor': vendor, 'items': items, 'total_cents': total}

