import xml.sax
import xml.sax.handler

class _OrderHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.order_id = None
        self.vendor = None
        self.items = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
            self.order_id = attrs.get('id')
            self.vendor = attrs.get('vendor')
        elif name == 'item':
            sku = attrs.get('sku')
            quantity_text = attrs.get('quantity')
            price_text = attrs.get('unit_price_cents')
            if sku is None or quantity_text is None or price_text is None:
                raise ValueError('missing item attribute')
            try:
                quantity = int(quantity_text)
                price = int(price_text)
            except ValueError as exc:
                raise ValueError('invalid item value') from exc
            if quantity <= 0 or price < 0:
                raise ValueError('invalid item value')
            self.items.append({'sku': sku, 'quantity': quantity, 'unit_price_cents': price})
        elif name != 'purchase_order':
            raise ValueError('unexpected element')

def parse_purchase_order(xml_text: str) -> dict:
    handler = _OrderHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        xml.sax.parseString(xml_text, handler)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'purchase_order':
        raise ValueError('wrong root element')
    if handler.order_id is None or handler.vendor is None:
        raise ValueError('missing order attribute')
    total = sum((item['quantity'] * item['unit_price_cents'] for item in handler.items))
    return {'order_id': handler.order_id, 'vendor': handler.vendor, 'items': handler.items, 'total_cents': total}

