import ast
import operator

def select_closings(applications: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval')
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc

    def evaluate(node: ast.AST, values: dict[str, object]):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, values)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise ValueError('unknown name')
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            fn = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
            return fn(evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            value = evaluate(node.operand, values)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
            result = evaluate(node.values[0], values)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(item, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            checks = []
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, values)
                fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}.get(type(op))
                if fn is None:
                    raise ValueError('unsupported rule')
                checks.append(fn(left, right))
                left = right
            return all(checks)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max'}) and (not node.keywords) and (len(node.args) >= 2):
            args = [evaluate(arg, values) for arg in node.args]
            return min(args) if node.func.id == 'min' else max(args)
        raise ValueError('unsupported rule')
    result = []
    for application in applications:
        values = {key: value for key, value in application.items() if key != 'borrower_id'}
        try:
            matched = evaluate(tree, values)
        except NameError as exc:
            raise ValueError('unknown name') from exc
        if matched:
            result.append(application['borrower_id'])
    return result

