import ast
import operator

def _evaluate(rule, values):
    try:
        tree = ast.parse(rule, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in values:
                    raise ValueError('unknown variable')
                return values[node.id]
            if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
                op = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
                return op(visit(node.left), visit(node.right))
            if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
                result = visit(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                        return result
                    result = visit(item)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, right_node in zip(node.ops, node.comparators):
                    right = visit(right_node)
                    if type(op) not in (ast.Lt, ast.LtE, ast.Eq, ast.NotEq, ast.Gt, ast.GtE):
                        raise ValueError('invalid expression')
                    if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                        return False
                    left = right
                return True
            raise ValueError('invalid expression')
        return visit(tree)
    except (SyntaxError, TypeError, ZeroDivisionError):
        raise ValueError('invalid expression')

def assign_gates(gates: list[dict[str, object]], rule: str) -> list[str]:
    selected = []
    for gate in gates:
        if gate['available'] and _evaluate(rule, {'capacity': gate['capacity'], 'distance': gate['distance'], 'international': gate['international']}):
            selected.append(gate)
    return [gate['name'] for gate in sorted(selected, key=lambda gate: (gate['distance'], gate['name']))]

