def parse_course_catalog(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'catalog':
        raise ValueError('root must be catalog')
    courses = []
    for course in root.findall('course'):
        if course.get('status') != 'published':
            continue
        instructor = course.findtext('instructor', default='')
        courses.append({'id': course.get('id', ''), 'title': course.get('title', ''), 'instructor': instructor})
    return sorted(courses, key=lambda item: item['id'])

