import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown name')
        return values[node.id]
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.Not):
            return not value
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        for kind, function in ops.items():
            if isinstance(node.op, kind):
                return function(left, right)
    if isinstance(node, ast.BoolOp):
        results = [_evaluate(x, values) for x in node.values]
        return all(results) if isinstance(node.op, ast.And) else any(results)
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, values)
            functions = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}
            if not any((isinstance(op, kind) and function(left, right) for kind, function in functions.items())):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}):
        if node.keywords:
            raise ValueError('invalid call')
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(x, values) for x in node.args])
    raise ValueError('invalid rule')

def choose_substitutions(items: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc
    selected = []
    for item in items:
        values = {'price': item['price'], 'stock': item['stock'], 'rating': item['rating']}
        if _evaluate(tree, values):
            selected.append(item)
    selected.sort(key=lambda item: (item['price'], item['name']))
    return [item['name'] for item in selected]

