import os
import shlex
import subprocess

def locate_recall_notices(directory: str, product_pattern: str) -> list[str]:
    paths = []
    for name in os.listdir(directory):
        path = os.path.join(directory, name)
        if os.path.isfile(path):
            paths.append(path)
    if not paths:
        return []
    quoted_paths = ' '.join((shlex.quote(path) for path in paths))
    result = subprocess.run(f"grep -l -e '{product_pattern}' {quoted_paths}", shell=True, capture_output=True, text=True)
    if result.returncode == 2:
        raise ValueError('invalid grep pattern')
    matches = []
    for line in result.stdout.splitlines():
        matches.append(os.path.basename(line))
    return sorted(matches)

