import ast
import operator

def _evaluate(expression, variables):
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id == 'True':
                return True
            if node.id == 'False':
                return False
            if node.id not in variables:
                raise ValueError('unknown variable')
            return variables[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp):
            ops = {ast.USub: operator.neg, ast.UAdd: operator.pos, ast.Not: operator.not_}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](visit(node.operand))
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for value in node.values:
                    result = visit(value)
                    if not result:
                        return result
                return result
            if isinstance(node.op, ast.Or):
                result = False
                for value in node.values:
                    result = visit(value)
                    if result:
                        return result
                return result
        if isinstance(node, ast.Compare):
            ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            left = visit(node.left)
            for op, item in zip(node.ops, node.comparators):
                if type(op) not in ops:
                    raise ValueError('unsupported expression')
                right = visit(item)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def rank_leads(leads: list[dict[str, object]], score_expression: str, filter_expression: str) -> list[tuple[str, float]]:
    ranked = []
    for lead in leads:
        score = _evaluate(score_expression, lead)
        if not isinstance(score, (int, float)) or isinstance(score, bool):
            raise ValueError('score is not numeric')
        if _evaluate(filter_expression, lead):
            ranked.append((lead['id'], score))
    ranked.sort(key=lambda item: item[1], reverse=True)
    return ranked

