import xml.etree.ElementTree as ET

def parse_fx_rates(xml_text: str) -> list[tuple[str, float]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'rates':
        raise ValueError('invalid root')
    result = []
    for element in root.findall('rate'):
        currency = element.get('currency')
        value_text = element.get('value')
        if currency is None or value_text is None or (not re.fullmatch('[A-Z]{3}', currency)):
            raise ValueError('invalid rate')
        try:
            value = float(value_text)
        except ValueError as exc:
            raise ValueError('invalid rate') from exc
        if not math.isfinite(value) or value <= 0:
            raise ValueError('invalid rate')
        result.append((currency, value))
    return sorted(result)

