import io
import math
import re
import xml.sax
import xml.sax.handler

class _RateHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.root = None
        self.depth = 0
        self.rates = []

    def startElement(self, name, attrs):
        if self.depth == 0:
            self.root = name
        elif self.depth == 1 and name == 'rate':
            self.rates.append((attrs.get('currency'), attrs.get('value')))
        self.depth += 1

    def endElement(self, name):
        self.depth -= 1

def parse_fx_rates(xml_text: str) -> list[tuple[str, float]]:
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    handler = _RateHandler()
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except xml.sax.SAXException as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'rates':
        raise ValueError('invalid root')
    result = []
    for currency, value_text in handler.rates:
        if currency is None or value_text is None or (not re.fullmatch('[A-Z]{3}', currency)):
            raise ValueError('invalid rate')
        try:
            value = float(value_text)
        except ValueError as exc:
            raise ValueError('invalid rate') from exc
        if not math.isfinite(value) or value <= 0:
            raise ValueError('invalid rate')
        result.append((currency, value))
    return sorted(result)

