import hashlib
import hmac
import json
import os

def create_shelter_record(shelter_name: str, access_pin: str, available_beds: int) -> str:
    if not shelter_name or not access_pin or available_beds < 0:
        raise ValueError('invalid shelter data')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_pin.encode(), salt, 100000)
    credential = salt.hex() + '$' + digest.hex()
    return json.dumps({'shelter': shelter_name, 'available_beds': available_beds, 'credential': credential})

def verify_shelter_pin(record: str, access_pin: str) -> bool:
    try:
        data = json.loads(record)
        credential = data['credential']
        salt_text, digest_text = credential.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', access_pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, KeyError, json.JSONDecodeError):
        return False

