import hashlib
import hmac
import json

def verify_asset_webhook(secret: str, body: str, signature: str) -> dict:
    expected = hmac.new(secret.encode('utf-8'), body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(data, dict) or not isinstance(data.get('brand'), str) or (not data['brand']):
        raise ValueError('invalid brand')
    assets = data.get('assets')
    if not isinstance(assets, list):
        raise ValueError('invalid assets')
    for asset in assets:
        if not isinstance(asset, dict):
            raise ValueError('invalid asset')
        if not isinstance(asset.get('name'), str) or not asset['name']:
            raise ValueError('invalid asset name')
        if not isinstance(asset.get('url'), str) or not asset['url']:
            raise ValueError('invalid asset url')
    return {'brand': data['brand'], 'assets': sorted(assets, key=lambda asset: asset['name'])}

