            writer.writerow(['event', 'customer', 'date', 'seats'])
            for booking in rows:
                writer.writerow([booking['event'], booking['customer'], booking['date'], booking['seats']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

