import hashlib
import hmac
import os

def create_aid_record(student_id: str, annual_income: int, credits: int) -> dict[str, str]:
    if annual_income < 0 or credits < 0:
        raise ValueError('annual income and credits must be non-negative')
    award = 5000 if annual_income <= 60000 and credits >= 12 else 0
    key = os.environ.get('AID_SIGNING_KEY')
    if key is None:
        raise RuntimeError('AID_SIGNING_KEY is required')
    payload = f'{student_id}:{award}'.encode()
    signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {'student_id': student_id, 'award': str(award), 'signature': signature}

