def export_flags(flags: dict[str, bool], destination: str) -> str:
    lines = []
    for name, value in flags.items():
        if not isinstance(name, str) or not name or '\n' in name or ('\r' in name):
            raise ValueError('invalid flag name')
        if not isinstance(value, bool):
            raise ValueError('flag value must be bool')
        lines.append(f"{name}={('on' if value else 'off')}")
    content = '' if not lines else '\n'.join(sorted(lines)) + '\n'
    directory = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8') as file:
            file.write(content)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return destination

